// Self-contained PDF 1.4 JPEG-to-PDF generator (compatible with window.jspdf.jsPDF)
(function (global) {
  function dataUrlToBytes(dataUrl) {
    const base64 = dataUrl.split(',')[1];
    const bin = atob(base64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  }

  function getJpegDimensions(bytes) {
    let i = 2;
    while (i < bytes.length - 9) {
      if (bytes[i] === 0xFF) {
        const marker = bytes[i + 1];
        if (marker === 0xC0 || marker === 0xC1 || marker === 0xC2) {
          const height = (bytes[i + 5] << 8) | bytes[i + 6];
          const width = (bytes[i + 7] << 8) | bytes[i + 8];
          return { width, height };
        }
        const segLen = (bytes[i + 2] << 8) | bytes[i + 3];
        i += 2 + segLen;
      } else {
        i++;
      }
    }
    return { width: 1280, height: 720 };
  }

  class MiniJsPDF {
    constructor(opts = {}) {
      const fmt = opts.format || [1280, 720];
      this.pageW = fmt[0] || 1280;
      this.pageH = fmt[1] || 720;
      this.pages = [[]];
    }

    addPage(fmt) {
      if (Array.isArray(fmt)) {
        this.pageW = fmt[0];
        this.pageH = fmt[1];
      }
      this.pages.push([]);
    }

    addImage(dataUrl, _type, x, y, w, h) {
      const bytes = dataUrlToBytes(dataUrl);
      const dims = getJpegDimensions(bytes);
      // Preserve native aspect ratio centered inside page bounds
      const scale = Math.min(w / dims.width, h / dims.height);
      const drawW = dims.width * scale;
      const drawH = dims.height * scale;
      const drawX = x + (w - drawW) / 2;
      const drawY = y + (h - drawH) / 2;

      this.pages[this.pages.length - 1].push({
        bytes,
        imgW: dims.width,
        imgH: dims.height,
        x: drawX,
        y: drawY,
        w: drawW,
        h: drawH
      });
    }

    save(filename = 'lecture-slides.pdf') {
      const enc = new TextEncoder();
      const chunks = [];
      let offset = 0;
      const offsets = [0];

      const pushStr = (str) => {
        const b = enc.encode(str);
        chunks.push(b);
        offset += b.length;
      };
      const pushBytes = (b) => {
        chunks.push(b);
        offset += b.length;
      };

      pushStr('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');

      const pageObjIds = [];
      let nextObjId = 3;
      const pageRecords = this.pages.map((items) => {
        const pageId = nextObjId++;
        const contentId = nextObjId++;
        const imgIds = items.map(() => nextObjId++);
        pageObjIds.push(pageId);
        return { pageId, contentId, items, imgIds };
      });

      offsets[1] = offset;
      pushStr('1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n');

      offsets[2] = offset;
      const kidsStr = pageObjIds.map(id => `${id} 0 R`).join(' ');
      pushStr(`2 0 obj\n<< /Type /Pages /Kids [ ${kidsStr} ] /Count ${pageObjIds.length} >>\nendobj\n`);

      for (const rec of pageRecords) {
        const xobjEntries = rec.imgIds.map((id, idx) => `/Im${idx} ${id} 0 R`).join(' ');
        offsets[rec.pageId] = offset;
        pushStr(
          `${rec.pageId} 0 obj\n` +
          `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${this.pageW} ${this.pageH}] ` +
          `/Resources << /XObject << ${xobjEntries} >> >> /Contents ${rec.contentId} 0 R >>\n` +
          `endobj\n`
        );

        let streamCmds = '';
        rec.items.forEach((item, idx) => {
          const pdfY = this.pageH - item.y - item.h;
          streamCmds += `q ${item.w.toFixed(2)} 0 0 ${item.h.toFixed(2)} ${item.x.toFixed(2)} ${pdfY.toFixed(2)} cm /Im${idx} Do Q\n`;
        });
        const streamBytes = enc.encode(streamCmds);
        offsets[rec.contentId] = offset;
        pushStr(`${rec.contentId} 0 obj\n<< /Length ${streamBytes.length} >>\nstream\n`);
        pushBytes(streamBytes);
        pushStr('\nendstream\nendobj\n');

        rec.items.forEach((item, idx) => {
          const imgObjId = rec.imgIds[idx];
          offsets[imgObjId] = offset;
          pushStr(
            `${imgObjId} 0 obj\n` +
            `<< /Type /XObject /Subtype /Image /Width ${item.imgW} /Height ${item.imgH} ` +
            `/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${item.bytes.length} >>\n` +
            `stream\n`
          );
          pushBytes(item.bytes);
          pushStr('\nendstream\nendobj\n');
        });
      }

      const xrefStart = offset;
      const totalObjs = nextObjId;
      pushStr(`xref\n0 ${totalObjs}\n`);
      pushStr('0000000000 65535 f \n');
      for (let i = 1; i < totalObjs; i++) {
        pushStr(`${String(offsets[i]).padStart(10, '0')} 00000 n \n`);
      }
      pushStr(
        `trailer\n<< /Size ${totalObjs} /Root 1 0 R >>\n` +
        `startxref\n${xrefStart}\n%%EOF`
      );

      const blob = new Blob(chunks, { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      a.click();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    }
  }

  global.jspdf = { jsPDF: MiniJsPDF };
})(window);
